with open(JUPITER_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    sagittarius_json = "      Sagittarius: " + json.dumps(sagittarius_data, indent=8) + ","
    new_content = content[:insertion_point] + "\n" + sagittarius_json + content[insertion_point:]
    
    with open(JUPITER_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Jupiter in Sagittarius to jupiter.js")
else:
    print("Could not find signs object in jupiter.js")
